def average(values):
    if not values:
        return 0
    return sum(values) / len(values)

def is_prime(number):
    if number < 2:
        return False
    for divisor in range(2, int(number ** 0.5) + 1):
        if number % divisor == 0:
            return False
    return True

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def common_items(left, right):
    result = []
    for value in left:
        if value in right and value not in result:
            result.append(value)
    return result

def second_largest(values):
    unique = sorted(set(values))
    if len(unique) < 2:
        return None
    return unique[-2]

def group_by_length(words):
    groups = {}
    for word in words:
        groups.setdefault(len(word), []).append(word)
    return groups
